application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  --ink: #18212f;
  --muted: #738096;
  --line: #e5e9f0;
  --accent: #6658d3;
  --accent-dark: #5144b9;
  --surface: #ffffff;
  --background: #f4f6fb;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--background);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.app-shell {
  width: min(100% - 32px, 680px);
  margin: 0 auto;
  padding: 64px 0 28px;
}

.todo-card {
  background: var(--surface);
  border: 1px solid rgba(30, 45, 75, .07);
  border-radius: 24px;
  box-shadow: 0 18px 55px rgba(55, 66, 100, .11);
  padding: 38px;
}

.app-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 32px;
}

.eyebrow {
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .16em;
  margin: 0 0 10px;
}

h1, h2, p { margin-top: 0; }
h1 { font-size: clamp(32px, 6vw, 44px); letter-spacing: -.045em; line-height: 1; margin-bottom: 10px; }
.subtitle { color: var(--muted); font-size: 15px; margin-bottom: 0; }

.header-mark {
  align-items: center;
  background: #eeecff;
  border-radius: 14px;
  color: var(--accent);
  display: flex;
  font-size: 25px;
  font-weight: 800;
  height: 52px;
  justify-content: center;
  width: 52px;
}

.task-form { display: flex; gap: 10px; margin-bottom: 34px; }
.task-form input {
  background: #fafbfe;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: var(--ink);
  flex: 1;
  font: inherit;
  min-width: 0;
  outline: none;
  padding: 14px 16px;
  transition: border-color .2s, box-shadow .2s;
}
.task-form input:focus { border-color: var(--accent); box-shadow: 0 0 0 4px rgba(102, 88, 211, .12); }
.task-form button {
  background: var(--accent);
  border: 0;
  border-radius: 11px;
  color: white;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
  padding: 0 18px;
  transition: background .2s, transform .2s;
}
.task-form button:hover { background: var(--accent-dark); }
.task-form button:active { transform: scale(.97); }
.task-form button span { font-size: 20px; line-height: 0; margin-left: 5px; vertical-align: -1px; }

.list-heading { align-items: center; display: flex; justify-content: space-between; margin-bottom: 13px; }
h2 { font-size: 17px; letter-spacing: -.01em; margin-bottom: 0; }
.count-pill { background: #f0efff; border-radius: 20px; color: var(--accent-dark); font-size: 12px; font-weight: 750; padding: 7px 11px; }
.count-label { font-weight: 600; }
.task-list { display: grid; gap: 9px; }
.task-item { align-items: center; border: 1px solid var(--line); border-radius: 12px; display: flex; gap: 12px; min-height: 58px; padding: 9px 11px 9px 14px; transition: background .2s, border-color .2s; }
.task-item:hover { background: #fbfbff; border-color: #d7d3fa; }
.complete-button { background: transparent; border: 2px solid #cbd1dd; border-radius: 50%; cursor: pointer; flex: 0 0 22px; height: 22px; padding: 0; position: relative; width: 22px; }
.task-item[data-completed="true"] .complete-button { background: var(--accent); border-color: var(--accent); }
.task-item[data-completed="true"] .complete-button::after { color: white; content: "✓"; font-size: 14px; font-weight: 800; left: 3px; position: absolute; top: -1px; }
.task-text { flex: 1; font-size: 15px; line-height: 1.4; overflow-wrap: anywhere; }
.task-item[data-completed="true"] .task-text { color: #9aa3b2; text-decoration: line-through; }
.delete-button { background: transparent; border: 0; border-radius: 7px; color: #a4adbb; cursor: pointer; font-size: 21px; line-height: 1; padding: 7px; }
.delete-button:hover { background: #fff0f1; color: #d75e6c; }
.empty-state { color: var(--muted); font-size: 14px; padding: 23px 0 10px; text-align: center; }
.page-note { color: #a1aabd; font-size: 12px; text-align: center; }
.sr-only { height: 1px; margin: -1px; overflow: hidden; position: absolute; width: 1px; clip: rect(0,0,0,0); }

@media (max-width: 520px) {
  .app-shell { padding-top: 25px; width: min(100% - 20px, 680px); }
  .todo-card { border-radius: 18px; padding: 25px 18px; }
  .task-form { align-items: stretch; flex-direction: column; }
  .task-form button { min-height: 48px; }
  .app-header { margin-bottom: 25px; }
}

application.javascript:
(() => {
  const form = document.getElementById('task-form');
  const input = document.getElementById('task-input');
  const list = document.querySelector('[data-testid="task-list"]');
  const count = document.querySelector('[data-testid="incomplete-count"]');
  const emptyState = document.getElementById('empty-state');
  let tasks = [];

  function updateCount() {
    count.textContent = String(tasks.filter(task => !task.completed).length);
    emptyState.hidden = tasks.length > 0;
  }

  function render() {
    list.innerHTML = '';
    tasks.forEach(task => {
      const item = document.createElement('article');
      item.className = 'task-item';
      item.dataset.testid = 'task';
      item.dataset.completed = String(task.completed);

      const complete = document.createElement('button');
      complete.type = 'button';
      complete.className = 'complete-button';
      complete.dataset.testid = 'task-complete';
      complete.setAttribute('aria-label', task.completed ? 'Mark task as incomplete' : 'Mark task as complete');
      complete.setAttribute('aria-pressed', String(task.completed));
      complete.addEventListener('click', () => {
        task.completed = !task.completed;
        render();
      });

      const text = document.createElement('span');
      text.className = 'task-text';
      text.dataset.testid = 'task-text';
      text.textContent = task.text;

      const remove = document.createElement('button');
      remove.type = 'button';
      remove.className = 'delete-button';
      remove.dataset.testid = 'task-delete';
      remove.setAttribute('aria-label', `Delete task: ${task.text}`);
      remove.textContent = '×';
      remove.addEventListener('click', () => {
        tasks = tasks.filter(current => current.id !== task.id);
        render();
      });

      item.append(complete, text, remove);
      list.appendChild(item);
    });
    updateCount();
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    const text = input.value.trim();
    if (!text) {
      input.focus();
      return;
    }
    tasks.push({ id: Date.now() + Math.random(), text, completed: false });
    input.value = '';
    render();
    input.focus();
  });

  render();
})();
